<?php
declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('GET');accounts_endpoint(function():array{$db=production_db();$s=$db->query("SELECT 'RECEIPT' record_type,w.id record_id,w.receipt_id,NULL receipt_allocation_id,w.tax_code_id,w.rate_snapshot,w.calculation_base_snapshot,NULL calculation_base_amount,w.accepted_amount,w.certificate_status,NULL certificate_evidence_id,w.created_at,r.reference_no,r.client_id,r.client_name_snapshot,r.receipt_date,NULL invoice_id FROM qbook_receipt_wht w JOIN qbook_customer_receipts r ON r.id=w.receipt_id WHERE w.certificate_status='CERTIFICATE_PENDING' UNION ALL SELECT 'ALLOCATION' record_type,aw.id record_id,r.id receipt_id,a.id receipt_allocation_id,aw.tax_code_id,aw.rate_snapshot,aw.calculation_base_snapshot,aw.calculation_base_amount,aw.accepted_amount,aw.certificate_status,aw.certificate_evidence_id,aw.created_at,r.reference_no,r.client_id,r.client_name_snapshot,r.receipt_date,a.invoice_id FROM qbook_customer_receipt_allocation_wht aw JOIN qbook_customer_receipt_allocations a ON a.id=aw.receipt_allocation_id JOIN qbook_customer_receipts r ON r.id=a.receipt_id WHERE aw.certificate_status='CERTIFICATE_PENDING' ORDER BY receipt_date,record_id");$rows=[];foreach($s->fetchAll()as$r){$r['receipt_reference']=billing_ref('RECEIPT',$r['reference_no']);$rows[]=$r;}return['certificates'=>$rows];});
